-- =============================================================================================
-- 068. property_and_calendar
-- ---------------------------------------------------------------------------------------------
-- Hand written.
--
-- The property hierarchy and the calendar of events.
--
-- Property hierarchy (module 2 - institution structure):
--   land              a land parcel of a campus (survey number, area, address)
--   floor             a floor of a building (number, name) - "floor id and floors to building"
--   facility_type     the catalogue of facilities: fire extinguisher, lift, AC, bench, ...
--   floor_facility    the facilities a floor carries (extinguishers, lifts, exits, ...)
--   room_facility     the facilities a room carries (AC, chairs or benches, projector, ...)
--   land_document     the documents of a parcel: sale deed, survey record, tax receipt
--   building_document the documents of a building: completion certificate, NOC, lift licence
--   building gains    land_id, total_floors, construction_year
--   room gains        floor_id, area_sqft
--
-- Calendar of events (module 3 - academic calendar):
--   calendar               the two calendars of an academic year: ACADEMIC and TERM
--   calendar_week          one row per week of the calendar of events
--   calendar_week_day      one row per day cell of a week (working day, holiday, exam, ...)
--   holiday                the holidays of a calendar (id, name, type)
--   calendar_term_schedule per course: term commencement, end of term, exam dates
--
-- Everything is connected: land -> building -> floor -> room, facilities and documents hang off
-- their parent with ON DELETE CASCADE, and the whole chain is campus scoped for RLS.
--
-- Rules this file obeys (the same ones 066 and 067 obey):
--   * Every new table is enabled for RLS and carries its four policies, its grants and its
--     audit_row trigger, so the admin catalogue can offer it for writing.
--   * The catalogue functions are re-created whole, with the new rows spliced in, because
--     `CREATE OR REPLACE` cannot change a function whose column list changed.
--   * tools/build_migrations.py and tools/build_rls.py know these objects belong to this file
--     (tools/hand_written.py) and leave them out of the generated set.
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- 1. Property hierarchy.
--
-- land -> building -> floor -> room, with the facility catalogue, the facilities a floor or a
-- room carries and the documents of a parcel and of a building.  `building` and `room` gain the
-- columns that hang them into the hierarchy.
-- ---------------------------------------------------------------------------------------------

CREATE TABLE public.land (
  land_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  campus_id u16 NOT NULL,
  land_name character varying(100) NOT NULL,
  survey_number character varying(50) NOT NULL,
  total_area_sqft numeric(12,2) NOT NULL DEFAULT 0,
  address text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT land_pkey PRIMARY KEY (land_id),
  CONSTRAINT uq_land_survey_number UNIQUE (survey_number),
  CONSTRAINT fk_land_campus FOREIGN KEY (campus_id) REFERENCES public.campus(campus_id)
);

CREATE TABLE public.floor (
  floor_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  building_id u16 NOT NULL,
  floor_number smallint NOT NULL,
  floor_name character varying(50),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT floor_pkey PRIMARY KEY (floor_id),
  CONSTRAINT uq_floor_building_number UNIQUE (building_id, floor_number),
  CONSTRAINT chk_floor_number CHECK (floor_number >= 0),
  CONSTRAINT fk_floor_building FOREIGN KEY (building_id) REFERENCES public.building(building_id) ON DELETE CASCADE
);

CREATE TABLE public.facility_type (
  facility_type_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  facility_code character varying(30) NOT NULL,
  facility_name character varying(100) NOT NULL,
  applies_to text NOT NULL,
  description character varying(500),
  is_active boolean NOT NULL DEFAULT true,
  CONSTRAINT facility_type_pkey PRIMARY KEY (facility_type_id),
  CONSTRAINT uq_facility_type_code UNIQUE (facility_code),
  CONSTRAINT enum_facility_applies_to CHECK (applies_to = ANY (ARRAY['FLOOR'::text, 'ROOM'::text, 'BOTH'::text]))
);

CREATE TABLE public.floor_facility (
  floor_facility_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  floor_id bigint NOT NULL,
  facility_type_id integer NOT NULL,
  quantity integer NOT NULL DEFAULT 1,
  notes character varying(500),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT floor_facility_pkey PRIMARY KEY (floor_facility_id),
  CONSTRAINT uq_floor_facility UNIQUE (floor_id, facility_type_id),
  CONSTRAINT chk_floor_facility_quantity CHECK (quantity > 0),
  CONSTRAINT fk_floor_facility_floor FOREIGN KEY (floor_id) REFERENCES public.floor(floor_id) ON DELETE CASCADE,
  CONSTRAINT fk_floor_facility_type FOREIGN KEY (facility_type_id) REFERENCES public.facility_type(facility_type_id)
);

CREATE TABLE public.room_facility (
  room_facility_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  room_id bigint NOT NULL,
  facility_type_id integer NOT NULL,
  quantity integer NOT NULL DEFAULT 1,
  notes character varying(500),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT room_facility_pkey PRIMARY KEY (room_facility_id),
  CONSTRAINT uq_room_facility UNIQUE (room_id, facility_type_id),
  CONSTRAINT chk_room_facility_quantity CHECK (quantity > 0),
  CONSTRAINT fk_room_facility_room FOREIGN KEY (room_id) REFERENCES public.room(room_id) ON DELETE CASCADE,
  CONSTRAINT fk_room_facility_type FOREIGN KEY (facility_type_id) REFERENCES public.facility_type(facility_type_id)
);

CREATE TABLE public.land_document (
  land_document_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  land_id bigint NOT NULL,
  document_type text NOT NULL,
  document_name character varying(200) NOT NULL,
  document_number character varying(100),
  issue_date date,
  expiry_date date,
  file_object_id bigint,
  remarks character varying(500),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT land_document_pkey PRIMARY KEY (land_document_id),
  CONSTRAINT enum_land_document_type CHECK (document_type = ANY (ARRAY['SALE_DEED'::text, 'SURVEY_RECORD'::text, 'TAX_RECEIPT'::text, 'COMPLETION_CERTIFICATE'::text, 'OCCUPANCY_CERTIFICATE'::text, 'FIRE_NOC'::text, 'LIFT_LICENSE'::text, 'BUILDING_PLAN'::text, 'OTHER'::text])),
  CONSTRAINT fk_land_document_land FOREIGN KEY (land_id) REFERENCES public.land(land_id) ON DELETE CASCADE,
  CONSTRAINT fk_land_document_file FOREIGN KEY (file_object_id) REFERENCES public.file_object(file_object_id)
);

CREATE TABLE public.building_document (
  building_document_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  building_id u16 NOT NULL,
  document_type text NOT NULL,
  document_name character varying(200) NOT NULL,
  document_number character varying(100),
  issue_date date,
  expiry_date date,
  file_object_id bigint,
  remarks character varying(500),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT building_document_pkey PRIMARY KEY (building_document_id),
  CONSTRAINT enum_building_document_type CHECK (document_type = ANY (ARRAY['COMPLETION_CERTIFICATE'::text, 'OCCUPANCY_CERTIFICATE'::text, 'FIRE_NOC'::text, 'LIFT_LICENSE'::text, 'BUILDING_PLAN'::text, 'INSPECTION_REPORT'::text, 'OTHER'::text])),
  CONSTRAINT fk_building_document_building FOREIGN KEY (building_id) REFERENCES public.building(building_id) ON DELETE CASCADE,
  CONSTRAINT fk_building_document_file FOREIGN KEY (file_object_id) REFERENCES public.file_object(file_object_id)
);

ALTER TABLE public.building
  ADD COLUMN land_id bigint,
  ADD COLUMN total_floors smallint,
  ADD COLUMN construction_year smallint;

ALTER TABLE public.building
  ADD CONSTRAINT fk_building_land FOREIGN KEY (land_id) REFERENCES public.land(land_id) ON DELETE SET NULL;

ALTER TABLE public.room
  ADD COLUMN floor_id bigint,
  ADD COLUMN area_sqft numeric(10,2);

ALTER TABLE public.room
  ADD CONSTRAINT fk_room_floor FOREIGN KEY (floor_id) REFERENCES public.floor(floor_id) ON DELETE SET NULL;

-- ---------------------------------------------------------------------------------------------
-- 2. Calendar of events.
--
-- Every academic year carries two calendars: the ACADEMIC one holds the week by week grid of
-- events (the calendar of events), the TERM one holds the term commencement and examination
-- schedule per course.
-- ---------------------------------------------------------------------------------------------

CREATE TABLE public.calendar (
  calendar_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  calendar_type text NOT NULL,
  academic_year_id integer NOT NULL,
  title character varying(150) NOT NULL,
  description text,
  start_date date,
  end_date date,
  is_published boolean NOT NULL DEFAULT false,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT calendar_pkey PRIMARY KEY (calendar_id),
  CONSTRAINT uq_calendar_year_type UNIQUE (academic_year_id, calendar_type),
  CONSTRAINT enum_calendar_type CHECK (calendar_type = ANY (ARRAY['ACADEMIC'::text, 'TERM'::text])),
  CONSTRAINT chk_calendar_dates CHECK (start_date IS NULL OR end_date IS NULL OR end_date >= start_date),
  CONSTRAINT fk_calendar_academic_year FOREIGN KEY (academic_year_id) REFERENCES public.academic_year(academic_year_id)
);

CREATE TABLE public.holiday (
  holiday_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  calendar_id bigint NOT NULL,
  holiday_date date NOT NULL,
  holiday_name character varying(150) NOT NULL,
  holiday_type text NOT NULL,
  is_optional boolean,
  description character varying(500),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT holiday_pkey PRIMARY KEY (holiday_id),
  CONSTRAINT uq_holiday_calendar_date UNIQUE (calendar_id, holiday_date),
  CONSTRAINT enum_holiday_type CHECK (holiday_type = ANY (ARRAY['GAZETTED'::text, 'RESTRICTED'::text, 'OPTIONAL'::text, 'INSTITUTIONAL'::text])),
  CONSTRAINT fk_holiday_calendar FOREIGN KEY (calendar_id) REFERENCES public.calendar(calendar_id) ON DELETE CASCADE
);

CREATE TABLE public.calendar_week (
  week_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  calendar_id bigint NOT NULL,
  week_no smallint NOT NULL,
  month_label character varying(20) NOT NULL,
  week_start_date date NOT NULL,
  week_end_date date NOT NULL,
  no_of_working_days smallint NOT NULL DEFAULT 0,
  events text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT calendar_week_pkey PRIMARY KEY (week_id),
  CONSTRAINT uq_calendar_week_number UNIQUE (calendar_id, week_no),
  CONSTRAINT chk_calendar_week_no CHECK (week_no > 0),
  CONSTRAINT chk_calendar_week_dates CHECK (week_end_date >= week_start_date),
  CONSTRAINT fk_calendar_week_calendar FOREIGN KEY (calendar_id) REFERENCES public.calendar(calendar_id) ON DELETE CASCADE
);

CREATE TABLE public.calendar_week_day (
  week_day_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  week_id bigint NOT NULL,
  day_index smallint NOT NULL,
  day_date date NOT NULL,
  day_category text NOT NULL DEFAULT 'WORKING_DAY',
  holiday_id bigint,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT calendar_week_day_pkey PRIMARY KEY (week_day_id),
  CONSTRAINT uq_calendar_week_day UNIQUE (week_id, day_index),
  CONSTRAINT chk_week_day_index CHECK (day_index BETWEEN 0 AND 6),
  CONSTRAINT enum_week_day_category CHECK (day_category = ANY (ARRAY['WORKING_DAY'::text, 'HOLIDAY'::text, 'MARKS_DISPLAY'::text, 'REMEDIAL_CLASS'::text, 'MAKEUP_EXAM'::text, 'MINOR_EXAM'::text])),
  CONSTRAINT fk_week_day_week FOREIGN KEY (week_id) REFERENCES public.calendar_week(week_id) ON DELETE CASCADE,
  CONSTRAINT fk_week_day_holiday FOREIGN KEY (holiday_id) REFERENCES public.holiday(holiday_id) ON DELETE SET NULL
);

CREATE TABLE public.calendar_term_schedule (
  term_schedule_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  calendar_id bigint NOT NULL,
  course_label character varying(200) NOT NULL,
  term_commencement_date date,
  end_of_term_date date,
  practical_exam_start date,
  practical_exam_end date,
  theory_exam_start date,
  theory_exam_end date,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT calendar_term_schedule_pkey PRIMARY KEY (term_schedule_id),
  CONSTRAINT uq_calendar_term_schedule UNIQUE (calendar_id, course_label),
  CONSTRAINT fk_term_schedule_calendar FOREIGN KEY (calendar_id) REFERENCES public.calendar(calendar_id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------------------------------
-- 3. Row level security.
-- ---------------------------------------------------------------------------------------------
ALTER TABLE public.land ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.floor ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.facility_type ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.floor_facility ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.room_facility ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.land_document ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.building_document ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.calendar ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.holiday ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.calendar_week ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.calendar_week_day ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.calendar_term_schedule ENABLE ROW LEVEL SECURITY;

-- property hierarchy, campus scope.  `land` carries the campus itself, everything below it
-- reaches the campus through its parent.
CREATE POLICY land_select ON public.land AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.READ'::text], (campus_id)::bigint));
CREATE POLICY land_insert ON public.land AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.CREATE'::text], (campus_id)::bigint));
CREATE POLICY land_update ON public.land AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], (campus_id)::bigint)) WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], (campus_id)::bigint));
CREATE POLICY land_delete ON public.land AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.DELETE'::text], (campus_id)::bigint));

CREATE POLICY floor_select ON public.floor AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.READ'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint)));
CREATE POLICY floor_insert ON public.floor AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.CREATE'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint)));
CREATE POLICY floor_update ON public.floor AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint))) WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint)));
CREATE POLICY floor_delete ON public.floor AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.DELETE'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint)));

-- the campus of a facility hangs two or three foreign keys away, so the policy walks the same
-- chain the admin catalogue's scope path walks.
CREATE POLICY floor_facility_select ON public.floor_facility AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.READ'::text], (SELECT b.campus_id::bigint FROM public.floor f JOIN public.building b ON b.building_id = f.building_id WHERE f.floor_id = floor_facility.floor_id)));
CREATE POLICY floor_facility_insert ON public.floor_facility AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.CREATE'::text], (SELECT b.campus_id::bigint FROM public.floor f JOIN public.building b ON b.building_id = f.building_id WHERE f.floor_id = floor_facility.floor_id)));
CREATE POLICY floor_facility_update ON public.floor_facility AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], (SELECT b.campus_id::bigint FROM public.floor f JOIN public.building b ON b.building_id = f.building_id WHERE f.floor_id = floor_facility.floor_id))) WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], (SELECT b.campus_id::bigint FROM public.floor f JOIN public.building b ON b.building_id = f.building_id WHERE f.floor_id = floor_facility.floor_id)));
CREATE POLICY floor_facility_delete ON public.floor_facility AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.DELETE'::text], (SELECT b.campus_id::bigint FROM public.floor f JOIN public.building b ON b.building_id = f.building_id WHERE f.floor_id = floor_facility.floor_id)));

CREATE POLICY room_facility_select ON public.room_facility AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.READ'::text], (SELECT b.campus_id::bigint FROM public.room r JOIN public.building b ON b.building_id = r.building_id WHERE r.room_id = room_facility.room_id)));
CREATE POLICY room_facility_insert ON public.room_facility AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.CREATE'::text], (SELECT b.campus_id::bigint FROM public.room r JOIN public.building b ON b.building_id = r.building_id WHERE r.room_id = room_facility.room_id)));
CREATE POLICY room_facility_update ON public.room_facility AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], (SELECT b.campus_id::bigint FROM public.room r JOIN public.building b ON b.building_id = r.building_id WHERE r.room_id = room_facility.room_id))) WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], (SELECT b.campus_id::bigint FROM public.room r JOIN public.building b ON b.building_id = r.building_id WHERE r.room_id = room_facility.room_id)));
CREATE POLICY room_facility_delete ON public.room_facility AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.DELETE'::text], (SELECT b.campus_id::bigint FROM public.room r JOIN public.building b ON b.building_id = r.building_id WHERE r.room_id = room_facility.room_id)));

CREATE POLICY land_document_select ON public.land_document AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.READ'::text], (SELECT l.campus_id::bigint FROM public.land l WHERE l.land_id = land_document.land_id)));
CREATE POLICY land_document_insert ON public.land_document AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.CREATE'::text], (SELECT l.campus_id::bigint FROM public.land l WHERE l.land_id = land_document.land_id)));
CREATE POLICY land_document_update ON public.land_document AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], (SELECT l.campus_id::bigint FROM public.land l WHERE l.land_id = land_document.land_id))) WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], (SELECT l.campus_id::bigint FROM public.land l WHERE l.land_id = land_document.land_id)));
CREATE POLICY land_document_delete ON public.land_document AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.DELETE'::text], (SELECT l.campus_id::bigint FROM public.land l WHERE l.land_id = land_document.land_id)));

CREATE POLICY building_document_select ON public.building_document AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.READ'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint)));
CREATE POLICY building_document_insert ON public.building_document AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.CREATE'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint)));
CREATE POLICY building_document_update ON public.building_document AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint))) WITH CHECK (sims_private.can_campus(ARRAY['INSTITUTION.ALL.UPDATE'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint)));
CREATE POLICY building_document_delete ON public.building_document AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_campus(ARRAY['INSTITUTION.ALL.DELETE'::text], sims_private.nx_building_building_id_campus_id((building_id)::bigint)));

-- the facility catalogue and the calendars are global: every active member may read them, the
-- configure permission governs every write.
CREATE POLICY facility_type_select ON public.facility_type AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.is_active_member());
CREATE POLICY facility_type_insert ON public.facility_type AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_global(ARRAY['INSTITUTION.ALL.CONFIGURE'::text]));
CREATE POLICY facility_type_update ON public.facility_type AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_global(ARRAY['INSTITUTION.ALL.CONFIGURE'::text])) WITH CHECK (sims_private.can_global(ARRAY['INSTITUTION.ALL.CONFIGURE'::text]));
CREATE POLICY facility_type_delete ON public.facility_type AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_global(ARRAY['INSTITUTION.ALL.CONFIGURE'::text]));

CREATE POLICY calendar_select ON public.calendar AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.is_active_member());
CREATE POLICY calendar_insert ON public.calendar AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY calendar_update ON public.calendar AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text])) WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY calendar_delete ON public.calendar AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));

CREATE POLICY holiday_select ON public.holiday AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.is_active_member());
CREATE POLICY holiday_insert ON public.holiday AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY holiday_update ON public.holiday AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text])) WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY holiday_delete ON public.holiday AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));

CREATE POLICY calendar_week_select ON public.calendar_week AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.is_active_member());
CREATE POLICY calendar_week_insert ON public.calendar_week AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY calendar_week_update ON public.calendar_week AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text])) WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY calendar_week_delete ON public.calendar_week AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));

CREATE POLICY calendar_week_day_select ON public.calendar_week_day AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.is_active_member());
CREATE POLICY calendar_week_day_insert ON public.calendar_week_day AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY calendar_week_day_update ON public.calendar_week_day AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text])) WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY calendar_week_day_delete ON public.calendar_week_day AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));

CREATE POLICY calendar_term_schedule_select ON public.calendar_term_schedule AS PERMISSIVE FOR SELECT TO authenticated USING (sims_private.is_active_member());
CREATE POLICY calendar_term_schedule_insert ON public.calendar_term_schedule AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY calendar_term_schedule_update ON public.calendar_term_schedule AS PERMISSIVE FOR UPDATE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text])) WITH CHECK (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));
CREATE POLICY calendar_term_schedule_delete ON public.calendar_term_schedule AS PERMISSIVE FOR DELETE TO authenticated USING (sims_private.can_global(ARRAY['ACADEMIC_CALENDAR.ALL.CONFIGURE'::text]));

